<?php require 'vendor/autoload.php'; $app = require_once 'bootstrap/app.php'; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $project = App\Models\Project::find(1); $costByCategory = \DB::table('components')->join('molds', 'components.mold_id', '=', 'molds.id')->join('stock_movements', 'components.id', '=', 'stock_movements.component_id')->where('molds.project_id', $project->id)->where('stock_movements.type', 'out')->where('stock_movements.status', 'approved')->select('components.category_id', \DB::raw('SUM(stock_movements.quantity * components.unit_price) as cost'))->groupBy('components.category_id')->get()->map(function($item) { $categoryName = $item->category_id ? \App\Models\ComponentCategory::find($item->category_id)->name ?? 'Uncategorized' : 'Uncategorized'; return ['category' => $categoryName, 'cost' => (float) $item->cost]; })->sortByDesc('cost')->values(); echo json_encode(['labels' => $costByCategory->pluck('category'), 'data' => $costByCategory->pluck('cost')]);
